 * - Line 435:
 *   declare function trace<T>(options: TraceOptions, fn: (span: Span$1) => T | Promise<T>): Promise<T>;
 * - Line 454:
 *   declare function init(options?: InitOptions): Promise<void>;
 *
 * node_modules/@opentelemetry/api/build/esm/trace/span.d.ts:
 * - Line 18-38:
 *   export interface Span {
 *     spanContext(): SpanContext;
 *     setAttribute(key: string, value: SpanAttributeValue): this;
 *     setAttributes(attributes: SpanAttributes): this;
 *   }
 */

export type SupportedSpanKind =
  | 'WORKFLOW'
  | 'AGENT'
  | 'CHAIN'
  | 'TOOL'
  | 'RETRIEVER'
  | 'EMBEDDING'
  | 'MCP_TOOL'
  | 'GUARDRAIL'
  | 'EVALUATOR';

let isTelemetryInitialized = false;

/**
 * Initializes neatlogs once from the environment.
 * Loads .env via process.loadEnvFile if NEATLOGS_API_KEY is not already present.
 */
export async function initTelemetry(workflowName = 'foreman'): Promise<void> {
  if (isTelemetryInitialized) {
    return;
  }

  if (!process.env.NEATLOGS_API_KEY && fs.existsSync('.env')) {
    try {
      loadEnvFile('.env');
    } catch {
      // Graceful fallback if .env cannot be loaded
    }
  }

  await init({
    workflowName,
  });

  isTelemetryInitialized = true;
}

/**
 * Creates the root WORKFLOW trace for a Foreman run.
 * Attaches runId and issueId attributes as supported by TraceOptions and Span.
 */
export async function withWorkflow<T>(
  runId: string,
  issueId: string | number,
  fn: (span: Span, traceId: string) => Promise<T>
): Promise<{ result: T; traceId: string }> {
  await initTelemetry('foreman');

  let traceId = '';

  const initialAttributes: Record<string, string | number> = {
    'foreman.run_id': runId,
    'foreman.issue_id': String(issueId),
  };

  const result = await trace(
    {
      name: `foreman-run-${runId}`,
      kind: 'WORKFLOW',
      sessionId: runId,
      attributes: initialAttributes,
    },
    async (span: Span) => {
      traceId = span.spanContext().traceId;
      // Statically supported attribute types in @opentelemetry/api
      span.setAttribute('foreman.run_id', runId);
      span.setAttribute('foreman.issue_id', String(issueId));
      return await fn(span, traceId);
    }
  );

  return { result, traceId };
}

/**
 * Creates a child span of a given kind within the active trace.
 * Allows attaching span attributes (e.g. baseline test counts).
 */
export async function withStage<T>(
  name: string,
  kind: SupportedSpanKind,
  fn: (span: Span) => Promise<T>,
  attributes?: Record<string, string | number | boolean>
): Promise<T> {
  return await trace(
    {
      name,
      kind,
      attributes,
    },
    async (span: Span) => {
      if (attributes) {
        for (const [key, value] of Object.entries(attributes)) {
          span.setAttribute(key, value);
        }
      }
      return await fn(span);
    }
  );
}

/**
 * Flushes all pending spans.
 */
export async function flushTelemetry(): Promise<boolean> {
  return await flush();
}

/**
 * Gracefully shuts down neatlogs exporter.
 */
export async function shutdownTelemetry(): Promise<boolean> {
  const result = await shutdown();
  isTelemetryInitialized = false;
  return result;
}

#!/usr/bin/env node
import { createWorkspace } from '../run/workspace.js';
import { runTests } from '../run/tests.js';
import { appendFact, readFacts } from '../state/facts.js';
import { deriveStatus } from '../state/derive.js';
import { withWorkflow, withStage, flushTelemetry, shutdownTelemetry } from '../telemetry/index.js';

interface CliArgs {
  command?: string;
  issue?: string;
  setupOnly: boolean;
}

function parseArgs(args: string[]): CliArgs {
  const result: CliArgs = {
    setupOnly: false,
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === 'run') {
      result.command = 'run';
    } else if (arg === '--issue') {
      result.issue = args[i + 1];
      i++;
    } else if (arg === '--setup-only') {
      result.setupOnly = true;
    }
  }

  return result;
}

export async function main(argv: string[] = process.argv.slice(2)): Promise<void> {
  const parsed = parseArgs(argv);

  if (parsed.command !== 'run' || !parsed.issue) {
    console.error('Usage: foreman run --issue <n> [--setup-only]');
    process.exit(1);
  }

  const issueId = parsed.issue;
  const runId = `run-${Date.now()}`;

  const { traceId } = await withWorkflow(runId, issueId, async (_span, currentTraceId) => {
    // 1. Record run_started fact
    appendFact(runId, {
      type: 'run_started',
      runId,
      issueId,
    });

    // 2. Set up workspace
    const workspace = await withStage('workspace_setup', 'TOOL', async (stageSpan) => {
      const ws = createWorkspace(runId, issueId);
      stageSpan.setAttribute('foreman.base_commit', ws.baseCommit);
      stageSpan.setAttribute('foreman.branch', ws.branch);
      stageSpan.setAttribute('foreman.path', ws.path);
      return ws;
    });

    appendFact(runId, {
      type: 'workspace_created',
      baseCommit: workspace.baseCommit,
      branch: workspace.branch,
      path: workspace.path,
    });

    // 3. Run baseline tests
    const baseline = await withStage(
      'baseline_tests',
      'EVALUATOR',
      async (stageSpan) => {
        const testRes = runTests(workspace.path);
        stageSpan.setAttribute('foreman.baseline.passed', testRes.passed);
        stageSpan.setAttribute('foreman.baseline.failed', testRes.failed);
        stageSpan.setAttribute('foreman.baseline.exit_code', testRes.exitCode);
        stageSpan.setAttribute('foreman.baseline.duration_ms', testRes.durationMs);
        return testRes;
      },
      {
        'foreman.run_id': runId,
        'foreman.issue_id': issueId,
      }
    );

    appendFact(runId, {
      type: 'baseline_recorded',
      exitCode: baseline.exitCode,
      passed: baseline.passed,
      failed: baseline.failed,
      failingTests: baseline.failingTests,
    });

    // 4. Derive status from facts
    const facts = readFacts(runId);
    const derivedStatus = deriveStatus(facts);

    // 5. Print summary (strictly no emojis)
    console.log('Foreman Run Summary');
    console.log('===================');
    console.log(`Run ID: ${runId}`);
    console.log(`Issue: ${issueId}`);
    console.log(`Derived Status: ${derivedStatus}`);
    console.log(`Trace ID: ${currentTraceId}`);
    console.log(`Workspace Path: ${workspace.path}`);
    console.log(`Base Commit: ${workspace.baseCommit}`);
    console.log(`Branch: ${workspace.branch}`);
    console.log(
      `Baseline Tests: ${baseline.passed} passed, ${baseline.failed} failed, exit code ${baseline.exitCode} (${baseline.durationMs}ms)`
    );
    if (baseline.failingTests.length > 0) {
      console.log(`Failing Tests: ${baseline.failingTests.join(', ')}`);
    }
    console.log(`Facts Count: ${facts.length}`);

    return { workspace, baseline, derivedStatus };
  });

  // Flush and clean shutdown
  await flushTelemetry();
  await shutdownTelemetry();
}

if (process.argv[1] && import.meta.url.endsWith(process.argv[1].replace(/\\/g, '/'))) {
  main().catch((err: unknown) => {
    console.error('Foreman CLI Error:', err);
    process.exit(1);
  });
}

